select
news.*
from news news

    and news.id = #{id}
    and news.title like concat('%',#{title},'%')
    and news.cover_img = #{coverImg}
    and news.content = #{content}
    and news.detail = #{detail}
    and news.status = #{status}
    and news.create_time = #{createTime}


    limit #{current},#{pageSize}

select count(*) from news news

    and news.id = #{id}
    and news.title like concat('%',#{title},'%')
    and news.cover_img = #{coverImg}
    and news.content = #{content}
    and news.detail = #{detail}
    and news.status = #{status}
    and news.create_time = #{createTime}
